import { trpc } from "@/lib/trpc";
import AdminEnhanced from "./AdminContentHub";
import MuseumEnhanced from "./MuseumJourney";
import QuizEnhanced from "./QuizEnhanced";
import WheelEnhanced from "./WheelEnhanced";
import FocusHub from "./FocusHub";
import Pomodoro from "./Pomodoro";
import KnowledgeMap from "./KnowledgeMap";
import StudyHistory from "./StudyHistory";
import ExamPrep from "./ExamPrep";
import ProgressReports from "./ProgressReports";
import AIDataImport from "./AIDataImport";
import { cn } from "@/lib/utils";
import { BRAND } from "@/branding";
import { Award, BarChart3, BookOpen, BrainCircuit, Check, ChevronLeft, ChevronRight, CircleHelp, Clock3, Dices, Download, FileUp, Flag, GraduationCap, History, LayoutDashboard, LockKeyhole, Menu, Moon, Plus, Search, ShieldCheck, Sparkles, Sun, Trophy, UsersRound, Volume2, VolumeX, WandSparkles, X } from "lucide-react";
import { ChangeEvent, FormEvent, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { applyStudyActivityRewards, computedAchievements, emptyAppConfig, validateGeneratedCards, validateGeneratedQuestions, emptyProfile, generateAchievements, levelForXp, normalizeProfile, statsForProfile, xpForNextLevel, limitFlashcards, type AppConfig, type Flashcard, type FlashcardSet, type ProfileState, type Quiz, type QuizQuestion, type StudyAccount, type StudySession } from "../../../shared/study";
import { createQuizFromFlashcardSet } from "../../../shared/quizPersistence";
import { isUnlimitedAccountCode } from "../../../shared/permissions";
import { isGitHubPages } from "@/lib/runtime";
import { sendSupabasePasswordReset, signInSupabase, signOutSupabase, signUpSupabase } from "@/lib/supabaseAuth";

type View = "dashboard" | "focus" | "pomodoro" | "knowledge" | "history" | "exam" | "progress" | "studio" | "ai-import" | "flashcards" | "quizzes" | "achievements" | "museum" | "wheel" | "account" | "admin" | "special111";
const SESSION_KEY = "study_historia_session_v1";
const uid = () => crypto.randomUUID();
const isAdmin = (a: StudyAccount) => a.role === "Admin" || a.role === "Founder";
const nav: { id: View; label: string; icon: typeof LayoutDashboard; admin?: boolean; special111?: boolean }[] = [
  { id: "dashboard", label: "Trang chủ", icon: LayoutDashboard }, { id: "special111", label: "Trung tâm 111", icon: WandSparkles, special111: true }, { id: "focus", label: "Ôn tập thông minh", icon: Sparkles }, { id: "ai-import", label: "Nhập dữ liệu AI", icon: FileUp }, { id: "pomodoro", label: "Pomodoro", icon: Clock3 }, { id: "knowledge", label: "Bản đồ kiến thức", icon: BarChart3 }, { id: "history", label: "Lịch sử học", icon: History }, { id: "exam", label: "Tôi sắp kiểm tra", icon: Flag }, { id: "progress", label: "Tiến trình", icon: BarChart3 }, { id: "studio", label: "AI Studio", icon: BrainCircuit }, { id: "flashcards", label: "Flashcard", icon: BookOpen }, { id: "quizzes", label: "Đề kiểm tra", icon: CircleHelp }, { id: "achievements", label: "Thành tích", icon: Trophy }, { id: "museum", label: "Bảo tàng hành trình", icon: History }, { id: "wheel", label: "Vòng quay tri thức", icon: Dices }, { id: "account", label: "Tài khoản", icon: UsersRound }, { id: "admin", label: "Admin Panel", icon: ShieldCheck, admin: true },
];

function storedSession(): StudySession | null { try { const item = sessionStorage.getItem(SESSION_KEY); return item ? JSON.parse(item) as StudySession : null; } catch { return null; } }
function parseCards(value: string): Flashcard[] { try { const raw = JSON.parse(value); const list = Array.isArray(raw) ? raw : raw?.cards; if (!Array.isArray(list)) return []; const cards = list.map((x) => ({ id: uid(), front: String(x.front ?? x.question ?? "").trim(), back: String(x.back ?? x.answer ?? "").trim(), status: "new" as const, starred: false })).filter((x) => x.front && x.back); return limitFlashcards(cards); } catch { return []; } }
function parseQuestions(value: string): QuizQuestion[] { try { const raw = JSON.parse(value); const list = Array.isArray(raw) ? raw : raw.questions; if (!Array.isArray(list)) return []; return list.map((x) => ({ id: uid(), type: x.type === "boolean" || x.type === "short" ? x.type : "multiple", prompt: String(x.prompt ?? x.question ?? ""), options: Array.isArray(x.options) ? x.options.map(String) : undefined, answer: String(x.answer ?? ""), explanation: String(x.explanation ?? "") })).filter((x) => x.prompt && x.answer); } catch { return []; } }

export default function Home() {
  const [session, setSession] = useState<StudySession | null>(() => isGitHubPages ? null : storedSession());
  const [profile, setProfile] = useState<ProfileState>(emptyProfile());
  const [config, setConfig] = useState<AppConfig>(emptyAppConfig());
  const [view, setView] = useState<View>("dashboard");
  const [menu, setMenu] = useState(false);
  const [supabaseBusy, setSupabaseBusy] = useState(false);
  const [search, setSearch] = useState("");
  const token = session?.token ?? "";
  const login = trpc.study.auth.login.useMutation();
  const logout = trpc.study.auth.logout.useMutation();
  const profileData = trpc.study.profile.get.useQuery({ token: token || "invalid-token" }, { enabled: Boolean(token) && !isGitHubPages, retry: false });
  const configData = trpc.study.config.get.useQuery(undefined, { enabled: !isGitHubPages, retry: false });
  const saveProfile = trpc.study.profile.save.useMutation();
  const saveConfig = trpc.study.config.save.useMutation();
  useEffect(() => { if (profileData.data?.profile) setProfile(normalizeProfile(profileData.data.profile)); }, [profileData.data]);
  useEffect(() => { if (configData.data) setConfig(configData.data as AppConfig); }, [configData.data]);
  useEffect(() => { if (profileData.error) { sessionStorage.removeItem(SESSION_KEY); setSession(null); } }, [profileData.error]);
  useEffect(() => { document.documentElement.classList.toggle("dark", profile.theme === "dark"); }, [profile.theme]);
  const persistProfile = (next: ProfileState, message?: string) => { const normalized = normalizeProfile(next); setProfile(normalized); if (isGitHubPages) { message && toast.success(message); return; } saveProfile.mutate({ token, profile: normalized }, { onSuccess: () => message && toast.success(message), onError: (e) => toast.error(e.message) }); };
  const persistConfig = (next: AppConfig, message?: string) => { setConfig(next); if (isGitHubPages) return; saveConfig.mutate({ token, config: next }, { onSuccess: () => message && toast.success(message), onError: (e) => toast.error(e.message) }); };
  const applySession = (data: StudySession) => { sessionStorage.setItem(SESSION_KEY, JSON.stringify(data)); setSession(data); toast.success(`Chào mừng ${data.account.name}`); };
  const submitLogin = async (data: { name: string; password: string; code: string; email?: string }) => {
    if (isGitHubPages) {
      if (!data.email) { toast.error("Bản Supabase cần email để đăng nhập."); return; }
      setSupabaseBusy(true);
      try { applySession(await signInSupabase({ email: data.email, password: data.password })); } catch (e) { toast.error(e instanceof Error ? e.message : "Không thể đăng nhập Supabase."); } finally { setSupabaseBusy(false); }
      return;
    }
    login.mutate({ name: data.name, password: data.password, code: data.code }, { onSuccess: applySession, onError: (e) => toast.error(e.message) });
  };
  const submitRegister = async (data: { name: string; password: string; code: string; email: string }) => {
    setSupabaseBusy(true);
    try { const result = await signUpSupabase(data); if (result.needsEmailConfirmation) toast.success("Đã tạo tài khoản. Hãy mở email để xác nhận, sau đó đăng nhập."); else applySession(result.session); } catch (e) { toast.error(e instanceof Error ? e.message : "Không thể tạo tài khoản Supabase."); } finally { setSupabaseBusy(false); }
  };
  const submitReset = async (email: string) => { setSupabaseBusy(true); try { await sendSupabasePasswordReset(email); toast.success("Đã gửi liên kết đặt lại mật khẩu vào email."); } catch (e) { toast.error(e instanceof Error ? e.message : "Không thể gửi email đặt lại mật khẩu."); } finally { setSupabaseBusy(false); } };
  if (!session) return <Login onSubmit={submitLogin} onRegister={submitRegister} onReset={submitReset} loading={login.isPending || supabaseBusy} staticHost={isGitHubPages} />;
  const account = session.account;
  const matches = search ? [...profile.flashcardSets.map((x) => ({ label: x.title, to: "flashcards" as View })), ...profile.quizzes.map((x) => ({ label: x.title, to: "quizzes" as View })), ...computedAchievements(profile, config).map((x) => ({ label: `${x.title} · Thành tích`, to: "achievements" as View })), ...config.characters.flatMap((x) => [{ label: x.name, to: "museum" as View }, { label: `Mảnh ghép · ${x.name}`, to: "museum" as View }])].filter((x) => x.label.toLowerCase().includes(search.toLowerCase())).slice(0, 5) : [];
  return <div className="min-h-screen bg-[#fffdf8] text-slate-800 dark:bg-[#241b16] dark:text-slate-100"><aside className={cn("fixed inset-y-0 left-0 z-50 flex w-72 flex-col border-r border-[#eadfd2] bg-white/95 p-4 backdrop-blur dark:border-white/10 dark:bg-[#241b16]/95 xl:translate-x-0", menu ? "translate-x-0" : "-translate-x-full", "transition-transform")}><Brand /> <nav className="mt-8 space-y-1">{nav.filter((x) => (!x.admin || isAdmin(account)) && (!x.special111 || isUnlimitedAccountCode(account.code))).map((x) => <Nav key={x.id} item={x} active={view === x.id} onClick={() => { setView(x.id); setMenu(false); }} />)}</nav><div className="mt-auto rounded-3xl bg-gradient-to-br from-[#8e1b1b] to-[#c62828] p-4 text-white"><p className="text-xs font-bold uppercase tracking-widest text-red-100">Cấp hiện tại</p><p className="mt-2 font-display text-3xl font-bold">Cấp {profile.level}</p><p className="mt-1 text-sm text-red-100">{profile.xp.toLocaleString("vi-VN")} XP</p><Progress value={Math.min(100, profile.xp / xpForNextLevel(profile.level) * 100)} className="mt-4 bg-white/20" /></div></aside>{menu && <button className="fixed inset-0 z-40 bg-slate-950/50 xl:hidden" onClick={() => setMenu(false)} aria-label="Đóng menu" />}<div className="xl:pl-72"><header className="sticky top-0 z-30 flex h-[74px] items-center gap-3 border-b border-[#eadfd2] bg-[#fffdf8]/95 px-4 backdrop-blur dark:border-white/10 dark:bg-[#241b16]/90 sm:px-7"><button onClick={() => setMenu(true)} className="icon-button xl:hidden" aria-label="Mở menu"><Menu className="h-5 w-5" /></button><div className="relative max-w-xl flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input aria-label={`Tìm kiếm trong ${BRAND.naturalName}`} value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm Flashcard, đề, nhân vật…" className="h-10 w-full rounded-xl border border-[#eadfd2] bg-white pl-9 pr-3 text-sm outline-none focus:border-[#c62828] focus:ring-2 focus:ring-[#c62828]/15 dark:border-white/10 dark:bg-slate-900" />{matches.length > 0 && <div className="absolute top-12 w-full rounded-xl border border-slate-200 bg-white p-1 shadow-xl dark:border-white/10 dark:bg-slate-900">{matches.map((x, i) => <button aria-label={`Mở kết quả tìm kiếm: ${x.label}`} key={i} onClick={() => { setView(x.to); setSearch(""); }} className="block w-full rounded-lg px-3 py-2 text-left text-sm hover:bg-slate-50 dark:hover:bg-white/5">{x.label}</button>)}</div>}</div><button aria-label={profile.theme === "dark" ? "Chuyển sang chế độ sáng" : "Chuyển sang chế độ tối"} onClick={() => persistProfile({ ...profile, theme: profile.theme === "dark" ? "light" : "dark" })} className="icon-button">{profile.theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button><button aria-label={profile.soundEnabled ? "Tắt âm thanh" : "Bật âm thanh"} onClick={() => persistProfile({ ...profile, soundEnabled: !profile.soundEnabled })} className="icon-button">{profile.soundEnabled ? <Volume2 className="h-4 w-4" /> : <VolumeX className="h-4 w-4" />}</button><div className="hidden gap-2 border-l border-slate-200 pl-3 sm:flex dark:border-white/10"><span className="grid h-10 w-10 place-items-center rounded-full bg-gradient-to-br from-[#f4b942] to-[#c62828] font-bold text-white">{account.name[0]}</span><span className="hidden lg:block"><b className="block max-w-32 truncate text-sm">{account.name}</b><small className="text-xs text-slate-500">{account.role}</small></span></div></header><main className="mx-auto max-w-[1500px] p-4 sm:p-7"><Views view={view} account={account} profile={profile} config={config} token={token} onView={setView} onProfile={persistProfile} onConfig={persistConfig} onLogout={() => { if (isGitHubPages) void signOutSupabase(); else logout.mutate({ token }); sessionStorage.removeItem(SESSION_KEY); setSession(null); }} /></main></div></div>;
}

function Login({ onSubmit, onRegister, onReset, loading, staticHost = false }: { onSubmit: (data: { name: string; password: string; code: string; email?: string }) => void | Promise<void>; onRegister?: (data: { name: string; password: string; code: string; email: string }) => void | Promise<void>; onReset?: (email: string) => void | Promise<void>; loading: boolean; staticHost?: boolean }) {
  const [mode, setMode] = useState<"login" | "register">("login");
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); const data = { name: String(d.get("name") ?? ""), password: String(d.get("password") ?? ""), code: String(d.get("code") ?? ""), email: String(d.get("email") ?? "") }; if (staticHost && mode === "register") return onRegister?.(data); onSubmit(data); };
  const reset = () => { const email = window.prompt("Nhập email Supabase để nhận liên kết đặt lại mật khẩu:"); if (email) void onReset?.(email); };
  const supabaseMode = staticHost && mode === "register";
  return <main className="min-h-screen bg-[radial-gradient(circle_at_12%_8%,#f4b94233,transparent_26%),radial-gradient(circle_at_88%_90%,#43a04722,transparent_30%),#fffdf8] px-5 py-10 text-slate-900"><div className="mx-auto grid min-h-[calc(100vh-5rem)] max-w-6xl items-center gap-10 lg:grid-cols-2"><section className="hidden lg:block"><Brand /><p className="mt-16 text-xs font-bold uppercase tracking-[.25em] text-[#8e1b1b]">Học · Chinh phục · Khám phá</p><h1 className="mt-5 max-w-xl font-display text-6xl font-bold leading-tight text-[#8e1b1b]">Mỗi lần học là một bước mở khóa câu chuyện.</h1><p className="mt-6 max-w-lg text-lg leading-8 text-slate-600">Flashcard, kiểm tra và hành trình khám phá lịch sử Việt Nam được kết nối trong một góc học tập riêng cho từng thành viên.</p></section><form onSubmit={submit} className="mx-auto w-full max-w-md rounded-[2rem] border border-[#eadfd2] bg-white p-7 shadow-[0_24px_70px_rgba(142,27,27,.12)]"><div className="lg:hidden"><Brand /></div>{staticHost && <div className="mt-6 grid grid-cols-2 gap-2 rounded-xl bg-[#f5f7f2] p-1"><button type="button" onClick={() => setMode("login")} className={cn("rounded-lg px-3 py-2 text-sm font-bold", !supabaseMode ? "bg-white text-[#8e1b1b] shadow-sm" : "text-slate-500")}>Đăng nhập</button><button type="button" onClick={() => setMode("register")} className={cn("rounded-lg px-3 py-2 text-sm font-bold", supabaseMode ? "bg-white text-[#8e1b1b] shadow-sm" : "text-slate-500")}>Tạo tài khoản</button></div>}<p className="mt-7 text-xs font-bold uppercase tracking-[.2em] text-[#2e7d32]">Phiên học riêng tư</p><h2 className="mt-2 font-display text-3xl font-bold text-[#8e1b1b]">{supabaseMode ? "Tạo tài khoản mới" : "Chào mừng trở lại"}</h2><p className="mt-2 text-sm text-slate-600">{staticHost ? "Bản GitHub Pages dùng Supabase Auth và cần email xác thực." : "Đăng nhập bằng tên, mật khẩu và mã thành viên được cấp."}</p><div className="mt-7 space-y-4">{staticHost && <Field name="email" type="email" label="Email" placeholder="ban@example.com" />} {!staticHost || supabaseMode ? <Field name="name" label="Tên thành viên" placeholder="Ví dụ: Nguyễn Văn An" /> : null}<Field name="password" type="password" label="Mật khẩu" placeholder="Tối thiểu 6 ký tự" />{!staticHost || supabaseMode ? <Field name="code" label="Mã thành viên" placeholder="Nhập mã thành viên được cấp" /> : null}<button aria-label={loading ? "Đang kiểm tra thông tin" : supabaseMode ? "Tạo tài khoản" : "Đăng nhập vào hành trình"} aria-busy={loading} disabled={loading} className="w-full rounded-xl bg-[#c62828] px-4 py-3.5 text-sm font-bold text-white shadow-lg shadow-red-900/15 transition hover:bg-[#8e1b1b] disabled:opacity-60">{loading ? "Đang xử lý…" : supabaseMode ? "Tạo tài khoản Supabase" : "Đăng nhập vào hành trình"}</button>{staticHost && !supabaseMode && <button type="button" disabled={loading} onClick={reset} className="w-full text-sm font-semibold text-[#8e1b1b] underline-offset-4 hover:underline">Quên mật khẩu?</button>}</div><p className={cn("mt-5 rounded-xl border p-3 text-xs leading-5", staticHost ? "border-amber-200 bg-amber-50 text-amber-800" : "border-[#dcebdc] bg-[#f5f7f2] text-[#2e7d32]")}>{staticHost ? "Tài khoản mới sẽ là Member. Founder/Admin cần được cấp từ hệ thống quản trị an toàn." : "Nhập mã thành viên được cấp bởi quản trị viên hoặc người phụ trách không gian học tập."}</p></form></div></main>;
}
function Brand({ dark = false }: { dark?: boolean }) { return <div className="flex items-center gap-3"><span aria-hidden="true" className="grid h-11 w-11 place-items-center rounded-2xl bg-gradient-to-br from-[#f4b942] to-[#c62828] text-white shadow-sm"><svg viewBox="0 0 64 64" className="h-7 w-7" role="img"><ellipse cx="32" cy="36" rx="15" ry="12" fill="currentColor" /><path d="M21 32h22M20 39h24" stroke="#f6cf63" strokeWidth="5" /><ellipse cx="22" cy="21" rx="10" ry="7" fill="#fff5cf" opacity=".9" transform="rotate(-25 22 21)" /><ellipse cx="42" cy="21" rx="10" ry="7" fill="#fff5cf" opacity=".9" transform="rotate(25 42 21)" /><circle cx="27" cy="34" r="2" fill="#fff5cf" /><circle cx="37" cy="34" r="2" fill="#fff5cf" /></svg></span><span><b className={cn("font-display block tracking-wide", dark ? "text-white" : "text-slate-950 dark:text-white")}>{BRAND.displayName}</b><small className="text-[10px] font-bold uppercase tracking-[.2em] text-amber-700 dark:text-amber-300">Hành trình tri thức</small></span></div>; }
function Nav({ item, active, onClick }: { item: { label: string; icon: typeof LayoutDashboard }; active: boolean; onClick: () => void }) { const Icon = item.icon; return <button aria-label={item.label} onClick={onClick} aria-current={active ? "page" : undefined} className={cn("flex w-full items-center gap-3 rounded-xl px-3.5 py-3 text-left text-sm font-bold", active ? "bg-[#c62828] text-white shadow-sm" : "text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-white/5")}><Icon className="h-[18px] w-[18px]" />{item.label}</button>; }
function Field({ name, label, placeholder, type = "text", dark = false }: { name: string; label: string; placeholder: string; type?: string; dark?: boolean }) { return <label className={cn("block text-sm font-bold", dark && "text-amber-50/90")}>{label}<input aria-label={label} required name={name} type={type} placeholder={placeholder} className={cn("mt-2 w-full rounded-xl border px-3.5 py-3 text-sm outline-none focus:border-[#c62828] focus:ring-2 focus:ring-[#c62828]/15", dark ? "border-white/15 bg-slate-950/30 text-white placeholder:text-slate-500" : "border-slate-200 bg-slate-50 dark:border-white/10 dark:bg-white/5")} /></label>; }
function Progress({ value, className = "" }: { value: number; className?: string }) { return <div className={cn("h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10", className)}><div className="h-full rounded-full bg-gradient-to-r from-[#c62828] via-[#e53935] to-[#43a047]" style={{ width: `${Math.min(100, value)}%` }} /></div>; }
function Heading({ eyebrow, title, text, action }: { eyebrow: string; title: string; text: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col gap-3 md:flex-row md:items-end md:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-amber-700 dark:text-amber-300">{eyebrow}</p><h1 className="mt-2 font-display text-3xl font-bold text-slate-950 dark:text-white sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{text}</p></div>{action}</div>; }
function Empty({ icon: Icon, title, text }: { icon: typeof Trophy; title: string; text: string }) { return <div className="grid min-h-48 place-items-center rounded-3xl border border-dashed border-slate-300 bg-white/60 p-8 text-center dark:border-white/10 dark:bg-white/[.025]"><div><Icon className="mx-auto h-6 w-6 text-slate-400" /><b className="mt-3 block">{title}</b><p className="mt-1 max-w-sm text-sm leading-6 text-slate-500">{text}</p></div></div>; }

function Views({ view, account, profile, config, token, onView, onProfile, onConfig, onLogout }: { view: View; account: StudyAccount; profile: ProfileState; config: AppConfig; token: string; onView: (v: View) => void; onProfile: (p: ProfileState, m?: string) => void; onConfig: (c: AppConfig, m?: string) => void; onLogout: () => void }) {
  if (view === "dashboard") return <Dashboard account={account} profile={profile} config={config} onView={onView} />;
  if (view === "special111") return isUnlimitedAccountCode(account.code) ? <Special111Dashboard account={account} profile={profile} onView={onView} /> : <Dashboard account={account} profile={profile} config={config} onView={onView} />;
  if (view === "focus") return <FocusHub profile={profile} config={config} onView={onView} onProfile={onProfile} />;
  if (view === "pomodoro") return <Pomodoro profile={profile} config={config} onProfile={onProfile} onView={onView} />;
  if (view === "knowledge") return <KnowledgeMap profile={profile} onView={onView} />;
  if (view === "history") return <StudyHistory profile={profile} />;
  if (view === "exam") return <ExamPrep profile={profile} onView={onView} />;
  if (view === "progress") return <><LearningProgress profile={profile} onView={onView} /><ProgressReports profile={profile} /></>;
  if (view === "studio") return <Studio profile={profile} onProfile={onProfile} onView={onView} token={token} />;
  if (view === "ai-import") return <AIDataImport profile={profile} onProfile={onProfile} onView={onView} />;
  if (view === "flashcards") return <Cards profile={profile} config={config} onProfile={onProfile} />;
  if (view === "quizzes") return <QuizEnhanced profile={profile} config={config} onProfile={onProfile} />;
  if (view === "achievements") return <Achievements profile={profile} config={config} />;
  if (view === "museum") return <MuseumEnhanced account={account} profile={profile} config={config} onView={onView} onProfile={onProfile} />;
  if (view === "wheel") return <WheelEnhanced profile={profile} config={config} onProfile={onProfile} />;
  if (view === "account") return <Account account={account} profile={profile} onProfile={onProfile} onLogout={onLogout} />;
  return <AdminEnhanced account={account} config={config} onConfig={onConfig} />;
}
function LearningProgress({ profile, onView }: { profile: ProfileState; onView: (view: View) => void }) { const stats = statsForProfile(profile); const activity = profile.studyActivity.length ? profile.studyActivity : profile.attempts.map((attempt) => ({ id: `legacy-${attempt.id}`, occurredAt: attempt.completedAt, kind: "quiz" as const, quantity: attempt.total, durationSeconds: attempt.durationSeconds, xpEarned: 0, correct: attempt.correct, total: attempt.total })); const todayStart = new Date(); todayStart.setHours(0, 0, 0, 0); const weekStart = new Date(todayStart); weekStart.setDate(weekStart.getDate() - 6); const today = activity.filter((item) => new Date(item.occurredAt) >= todayStart); const week = activity.filter((item) => new Date(item.occurredAt) >= weekStart); const quizAttempts = profile.attempts.filter((attempt) => new Date(attempt.completedAt) >= weekStart); const totalCorrect = quizAttempts.reduce((sum, attempt) => sum + attempt.correct, 0); const totalQuestions = quizAttempts.reduce((sum, attempt) => sum + attempt.total, 0); const studyDays = new Set(activity.map((item) => new Date(item.occurredAt).toLocaleDateString("vi-VN"))); const recentDays = Array.from({ length: 7 }, (_, index) => { const day = new Date(todayStart); day.setDate(day.getDate() - (6 - index)); const key = day.toLocaleDateString("vi-VN"); const count = activity.filter((item) => new Date(item.occurredAt).toLocaleDateString("vi-VN") === key).reduce((sum, item) => sum + item.quantity, 0); return { label: day.toLocaleDateString("vi-VN", { weekday: "short" }).replace("T", "T"), count }; }); const maxDaily = Math.max(1, ...recentDays.map((day) => day.count)); const quizById = new Map(profile.quizzes.map((quiz) => [quiz.id, quiz])); const modeRows = (["quick", "deep", "paper"] as const).map((mode) => { const attempts = profile.attempts.filter((attempt) => (attempt.mode ?? "quick") === mode); const correct = attempts.reduce((sum, attempt) => sum + attempt.correct, 0); const total = attempts.reduce((sum, attempt) => sum + attempt.total, 0); return { mode, label: mode === "quick" ? "Làm đề nhanh" : mode === "deep" ? "Hiểu tận gốc" : "Tự làm đề–Tập trung", count: attempts.length, accuracy: total ? Math.round(correct / total * 100) : 0 }; }); const topicMap = new Map<string, { subject: string; topic: string; attempts: number; correct: number; total: number }>(); profile.attempts.forEach((attempt) => { const quiz = quizById.get(attempt.quizId); const subject = quiz?.subject || "Chưa phân loại"; const topic = quiz?.topic || quiz?.title || "Chưa có chủ đề"; const key = `${subject} · ${topic}`; const row = topicMap.get(key) ?? { subject, topic, attempts: 0, correct: 0, total: 0 }; row.attempts += 1; row.correct += attempt.correct; row.total += attempt.total; topicMap.set(key, row); }); const topicRows = Array.from(topicMap.values()).sort((a, b) => (b.correct / Math.max(1, b.total)) - (a.correct / Math.max(1, a.total))).slice(0, 6).map((row) => ({ ...row, accuracy: Math.round(row.correct / Math.max(1, row.total) * 100) })); const formatDuration = (seconds: number) => { const minutes = Math.round(seconds / 60); return minutes >= 60 ? `${Math.floor(minutes / 60)} giờ ${minutes % 60} phút` : `${minutes} phút`; }; return <><Heading eyebrow="Tiến trình học tập" title="Dữ liệu của chính hành trình bạn" text="Báo cáo chỉ tổng hợp lượt học, đề đã nộp và thời lượng đã ghi nhận trong hồ sơ của bạn." action={<button className="primary-button" onClick={() => onView("pomodoro")}><Clock3 className="h-4 w-4" />Mở Pomodoro</button>} /><section className="panel mb-5 flex flex-wrap items-center justify-between gap-4 p-5"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Module trung tâm</p><h2 className="mt-2 font-display text-2xl font-bold">Pomodoro · biến thời gian thành tiến trình</h2><p className="mt-2 text-sm text-slate-500">Phiên hoàn thành liên kết với Flashcard, Đề kiểm tra, XP, Thành tích và Mảnh ghép mà không trộn dữ liệu các module.</p></div><div className="flex flex-wrap gap-2"><button className="secondary-button" onClick={() => onView("flashcards")}><BookOpen className="h-4 w-4" />Flashcard</button><button className="secondary-button" onClick={() => onView("quizzes")}><CircleHelp className="h-4 w-4" />Đề kiểm tra</button></div></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={BookOpen} label="Lượt học hôm nay" value={today.reduce((sum, item) => sum + item.quantity, 0)} detail={`${today.filter((item) => item.kind === "flashcard").length} lần ôn thẻ`} /><Stat icon={Clock3} label="Thời gian đã ghi nhận" value={formatDuration(stats.studySeconds)} detail="Từ đề kiểm tra đã nộp" /><Stat icon={CircleHelp} label="Độ chính xác 7 ngày" value={totalQuestions ? `${Math.round(totalCorrect / totalQuestions * 100)}%` : "—"} detail={totalQuestions ? `${totalCorrect}/${totalQuestions} câu đúng` : "Chưa có đề trong 7 ngày"} /><Stat icon={Sparkles} label="Ngày có hoạt động" value={studyDays.size} detail="Tính trên toàn bộ lịch sử" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.85fr]"><section className="panel p-6"><div className="flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">7 ngày gần đây</p><h2 className="mt-2 font-display text-2xl font-bold">Nhịp học theo ngày</h2></div><b className="text-sm text-slate-500">{week.reduce((sum, item) => sum + item.quantity, 0)} lượt học</b></div><div className="mt-8 grid h-48 grid-cols-7 items-end gap-3" role="img" aria-label="Biểu đồ lượt học trong bảy ngày gần đây">{recentDays.map((day) => <div className="flex h-full flex-col justify-end" key={day.label}><div className="rounded-t-xl bg-gradient-to-t from-amber-500 to-yellow-300 transition-[height]" style={{ height: `${Math.max(day.count ? 14 : 3, day.count / maxDaily * 100)}%` }} title={`${day.label}: ${day.count} lượt học`} /><span className="mt-2 text-center text-[11px] font-bold text-slate-500">{day.label}</span></div>)}</div></section><section className="panel p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Tổng hành trình</p><h2 className="mt-2 font-display text-2xl font-bold">Học một cách có chủ đích</h2><dl className="mt-6 space-y-4 text-sm"><div className="flex justify-between gap-4"><dt className="text-slate-500">Flashcard đã nhớ</dt><dd className="font-bold">{stats.learnedCards}</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">Bộ hoàn tất</dt><dd className="font-bold">{stats.completedSets}</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">Đề đã hoàn thành</dt><dd className="font-bold">{stats.completedQuizzes}</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">XP tích lũy</dt><dd className="font-bold">{profile.xp.toLocaleString("vi-VN")}</dd></div></dl></section></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><section className="panel p-6" aria-labelledby="progress-mode-chart"><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Theo chế độ</p><h2 id="progress-mode-chart" className="mt-2 font-display text-2xl font-bold">Cách bạn đang học</h2><div className="mt-6 space-y-4">{modeRows.map((row) => <div key={row.mode}><div className="mb-2 flex items-center justify-between gap-3 text-sm"><span className="font-bold">{row.label}</span><span className="text-slate-500">{row.count} phiên · {row.accuracy}% đúng</span></div><div className="h-3 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10"><div className="h-full rounded-full bg-gradient-to-r from-amber-500 to-yellow-300" style={{ width: `${row.count ? Math.max(8, row.accuracy) : 0}%` }} /></div></div>)}</div></section><section className="panel p-6" aria-labelledby="progress-topic-chart"><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Theo chủ đề</p><h2 id="progress-topic-chart" className="mt-2 font-display text-2xl font-bold">Chủ đề nổi bật</h2>{topicRows.length ? <div className="mt-5 space-y-3">{topicRows.map((row) => <div className="rounded-2xl border border-slate-100 p-3 dark:border-white/10" key={`${row.subject}-${row.topic}`}><div className="flex items-center justify-between gap-3"><div className="min-w-0"><b className="block truncate text-sm">{row.topic}</b><span className="text-xs text-slate-500">{row.subject} · {row.attempts} phiên</span></div><strong className="text-sm text-amber-700">{row.accuracy}%</strong></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10"><div className="h-full rounded-full bg-emerald-500" style={{ width: `${row.accuracy}%` }} /></div></div>)}</div> : <p className="mt-5 text-sm text-slate-500">Chưa có dữ liệu chủ đề từ các đề đã hoàn thành.</p>}</section></div></>; }
function Special111Dashboard({ account, profile, onView }: { account: StudyAccount; profile: ProfileState; onView: (v: View) => void }) { const quick = [{ icon: Sparkles, label: "Ôn tập thông minh", detail: "Bắt đầu một nhịp học ngắn", view: "focus" as View }, { icon: Clock3, label: "Pomodoro", detail: "Tập trung và ghi nhận phiên", view: "pomodoro" as View }, { icon: BrainCircuit, label: "AI Studio", detail: "Tạo Flashcard hoặc Đề kiểm tra", view: "studio" as View }, { icon: Trophy, label: "Thành tích", detail: "Theo dõi 900 mốc tiến bộ", view: "achievements" as View }]; return <><Heading eyebrow="Khu vực đặc biệt · Mã 111" title={`Trung tâm điều khiển của ${account.name}`} text="Tài khoản 111 được miễn giới hạn. Từ đây, Ong có thể mở nhanh các công cụ học tập cốt lõi và theo dõi nhịp học của mình." action={<span className="rounded-full border border-amber-300 bg-amber-50 px-4 py-2 text-xs font-bold text-amber-800 dark:border-amber-400/30 dark:bg-amber-400/10 dark:text-amber-200">Mã 111 · Không giới hạn</span>} /><section className="mb-5 overflow-hidden rounded-[2rem] bg-gradient-to-br from-[#6b1f1f] via-[#a94c1f] to-[#f4b942] p-6 text-white shadow-xl shadow-amber-500/20 sm:p-8"><div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-amber-100">Lối vào nhanh</p><h2 className="mt-3 font-display text-3xl font-bold sm:text-4xl">Học theo cách của Ong</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-amber-50">Mã 111 mở sẵn các lối tắt để bạn chuyển từ ý định sang hành động chỉ trong một chạm.</p></div><div className="rounded-2xl border border-white/20 bg-white/10 px-5 py-4 text-center backdrop-blur"><p className="text-xs uppercase tracking-widest text-amber-100">XP hiện tại</p><b className="mt-1 block text-3xl">{profile.xp.toLocaleString("vi-VN")}</b></div></div></section><section aria-label="Menu truy cập nhanh dành cho mã 111" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{quick.map(({ icon: Icon, label, detail, view }) => <button key={view} onClick={() => onView(view)} className="group rounded-3xl border border-amber-200 bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-amber-400 hover:shadow-lg dark:border-amber-400/20 dark:bg-white/[.04]"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-amber-100 text-amber-800 transition group-hover:bg-[#c62828] group-hover:text-white dark:bg-amber-400/15 dark:text-amber-200"><Icon className="h-5 w-5" /></span><b className="mt-4 block text-base">{label}</b><span className="mt-1 block text-sm leading-5 text-slate-500">{detail}</span><span className="mt-4 block text-xs font-bold uppercase tracking-widest text-[#c62828]">Mở ngay →</span></button>)}</section><section className="mt-5 grid gap-5 lg:grid-cols-2"><div className="panel p-6"><p className="text-xs font-bold uppercase tracking-widest text-amber-700 dark:text-amber-300">Trạng thái hôm nay</p><h2 className="mt-2 font-display text-2xl font-bold">{profile.studyActivity.length ? "Ong đang giữ nhịp rất tốt" : "Bắt đầu một nhịp học đầu tiên"}</h2><p className="mt-3 text-sm leading-6 text-slate-500">{profile.studyActivity.length ? `Đã ghi nhận ${profile.studyActivity.length} hoạt động trong hồ sơ học tập.` : "Chọn một lối vào nhanh ở trên để bắt đầu và lưu lại tiến trình."}</p></div><div className="panel p-6"><p className="text-xs font-bold uppercase tracking-widest text-amber-700 dark:text-amber-300">Quyền đặc biệt</p><div className="mt-4 grid gap-3 text-sm"><div className="flex items-center gap-3"><Check className="h-4 w-4 text-emerald-600" />Không bị giới hạn khóa tài khoản</div><div className="flex items-center gap-3"><Check className="h-4 w-4 text-emerald-600" />Truy cập nhanh các công cụ học tập</div><div className="flex items-center gap-3"><Check className="h-4 w-4 text-emerald-600" />Dữ liệu vẫn được lưu theo hồ sơ riêng</div></div></div></section></>; }
function Dashboard({ account, profile, config, onView }: { account: StudyAccount; profile: ProfileState; config: AppConfig; onView: (v: View) => void }) { const stats = statsForProfile(profile); const achieved = computedAchievements(profile, config); const dayIndex = Math.floor(Date.now() / 86400000); const dailyEncouragements = config.encouragements.filter((entry) => entry.enabled); const dailyGreeting = dailyEncouragements.length ? dailyEncouragements[dayIndex % dailyEncouragements.length].text : "Ong hôm nay thế nào? Mình học một chút, vừa đủ để ngày mai nhẹ hơn."; const start = new Date(); start.setHours(0, 0, 0, 0); const todayActivities = profile.studyActivity.filter((activity) => new Date(activity.occurredAt) >= start); const todaySeconds = todayActivities.reduce((sum, activity) => sum + activity.durationSeconds, 0); const todayCards = todayActivities.filter((activity) => activity.kind === "flashcard").reduce((sum, activity) => sum + activity.quantity, 0); const todayQuizzes = todayActivities.filter((activity) => activity.kind === "quiz").length; const targetSeconds = 3 * 60 * 60; const timeLabel = todaySeconds >= 3600 ? `${Math.floor(todaySeconds / 3600)} giờ ${Math.floor(todaySeconds % 3600 / 60)} phút` : `${Math.floor(todaySeconds / 60)} phút`; return <><Heading eyebrow="Góc học tập của Ong" title={`Chào ${account.name.split(" ").at(-1)}!`} text={dailyGreeting} action={<button onClick={() => onView("focus")} className="primary-button"><Sparkles className="h-4 w-4" />Học 10 phút</button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Clock3} label="Thời gian học hôm nay" value={timeLabel} detail="Từ phiên đã ghi nhận" /><Stat icon={BookOpen} label="Flashcard đã học" value={todayCards} detail={`${stats.learnedCards} thẻ đã nhớ`} /><Stat icon={CircleHelp} label="Đề đã hoàn thành" value={todayQuizzes} detail={`${stats.completedQuizzes} đề toàn bộ`} /><Stat icon={Trophy} label="Thành tích mới" value={`${achieved.length}/900`} detail={`${stats.fragments} mảnh ghép`} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.85fr]"><section className="rounded-3xl bg-gradient-to-br from-[#6b4f35] via-[#c9822c] to-[#f4b942] p-6 text-white shadow-xl shadow-amber-500/20"><p className="text-xs font-bold uppercase tracking-[.18em] text-amber-100">Tiến trình hôm nay</p><h2 className="mt-3 font-display text-3xl font-bold">{timeLabel} / 3 giờ</h2><p className="mt-3 max-w-xl text-sm leading-6 text-amber-50">{todaySeconds >= targetSeconds ? "Bạn đã hoàn thành nhịp học hôm nay. Ong rất tự hào về bạn!" : "Chỉ còn một chút nữa thôi. Ong đang làm rất tốt!"}</p><div className="mt-9 flex items-center gap-4"><Progress value={todaySeconds / targetSeconds * 100} className="flex-1 bg-white/20" /><b>{Math.min(100, Math.round(todaySeconds / targetSeconds * 100))}%</b></div></section><section className="study-card p-5"><p className="text-xs font-bold uppercase tracking-[.16em] text-slate-400">Học tiếp một cách nhẹ nhàng</p><div className="mt-4 space-y-2"><Quick icon={BrainCircuit} text="Tạo nội dung từ dữ liệu AI" click={() => onView("ai-import")} /><Quick icon={BookOpen} text="Ôn Flashcard chưa chắc" click={() => onView("focus")} /><Quick icon={History} text="Khám phá câu chuyện lịch sử" click={() => onView("museum")} /></div></section></div></>;
}
function Stat({ icon: Icon, label, value, detail }: { icon: typeof Award; label: string; value: string | number; detail: string }) { const tone = label.includes("Thời gian") ? "semantic-info" : label.includes("Flashcard") ? "semantic-positive" : label.includes("Đề") ? "semantic-special" : "semantic-challenge"; return <div className="study-card p-5"><div className="flex justify-between gap-3"><span className={cn("grid h-11 w-11 place-items-center rounded-2xl", tone)}><Icon className="h-5 w-5" /></span><small className="pt-1 text-right text-slate-400">{detail}</small></div><b className="mt-5 block text-3xl text-slate-950 dark:text-white">{typeof value === "number" ? value.toLocaleString("vi-VN") : value}</b><p className="mt-1 text-sm text-slate-500">{label}</p></div>; }
