function Studio({ profile, onProfile, onView, token }: { profile: ProfileState; onProfile: (p: ProfileState, m?: string) => void; onView: (v: View) => void; token: string }) { const [tab, setTab] = useState<"cards" | "quiz" | "both">("cards"); const [title, setTitle] = useState(""); const [subject, setSubject] = useState(""); const [purpose, setPurpose] = useState(""); const [topic, setTopic] = useState(""); const [source, setSource] = useState(""); const [schoolLevel, setSchoolLevel] = useState(""); const [difficulty, setDifficulty] = useState<"Cơ bản" | "Trung bình" | "Nâng cao">("Trung bình"); const [requirements, setRequirements] = useState(""); const [sourceFileName, setSourceFileName] = useState(""); const [sourceFileContent, setSourceFileContent] = useState(""); const [sourceFileDataUrl, setSourceFileDataUrl] = useState(""); const [sourceFileContentType, setSourceFileContentType] = useState<"text/plain" | "text/markdown" | "application/pdf">(); const generateFromDocument = trpc.study.ai.generateFromDocument.useMutation({ onSuccess: (data) => { setResult(data.content); toast.success("AI đã tạo JSON từ tài liệu."); }, onError: (error) => toast.error(error.message) }); const [questionCount, setQuestionCount] = useState(10); const [durationMinutes, setDurationMinutes] = useState(20); const [multipleRatio, setMultipleRatio] = useState(60); const [booleanRatio, setBooleanRatio] = useState(20); const [answerOptionCount, setAnswerOptionCount] = useState(4); const [includeAnswerKey, setIncludeAnswerKey] = useState(true); const [result, setResult] = useState(""); const [promptDraft, setPromptDraft] = useState(""); const shortRatio = Math.max(0, 100 - multipleRatio - booleanRatio); const generatedPrompt = tab === "cards" ? `Tạo tối đa 27 Flashcard tiếng Việt cho môn ${subject || "[môn học]"}, mục đích ${purpose || "[mục đích học]"}, lớp ${schoolLevel || "[lớp học]"}, chủ đề ${topic || "[chủ đề]"}, mức độ ${difficulty}. Yêu cầu: ${requirements || "[yêu cầu]"}. Dựa vào: ${sourceFileContent || source || (sourceFileName ? `tệp ${sourceFileName}` : "[tài liệu]")}. Chỉ trả về JSON: [{"front":"câu hỏi","back":"đáp án"}].` : `Tạo đề kiểm tra ${questionCount} câu, thời gian ${durationMinutes} phút, môn ${subject || "[môn học]"}, lớp ${schoolLevel || "[lớp học]"}, chủ đề ${topic || "[chủ đề]"}, mức độ ${difficulty}. Tỷ lệ: trắc nghiệm ${multipleRatio}%, đúng/sai ${booleanRatio}%, trả lời ngắn ${shortRatio}%. Mỗi câu trắc nghiệm có ${answerOptionCount} lựa chọn. ${includeAnswerKey ? "Bao gồm đáp án và giải thích." : "Không đưa đáp án mẫu, chỉ tạo câu hỏi."} Yêu cầu: ${requirements || "[yêu cầu]"}. Chỉ trả về JSON {"questions":[{"type":"multiple|boolean|short","prompt":"...","options":["A","B","C","D"],"answer":"...","explanation":"..."}]}`;
  useEffect(() => { setPromptDraft(generatedPrompt); }, [generatedPrompt]); const prompt = promptDraft || generatedPrompt; const generate = () => { if (!subject) return toast.error("Hãy nhập môn học trước."); generateFromDocument.mutate({ token, mode: tab, prompt, fileName: sourceFileName || undefined, contentType: sourceFileContentType, dataUrl: sourceFileDataUrl || undefined }); }; const create = () => { if (!title || !subject) return toast.error("Hãy nhập tên và môn học."); if (tab === "both") { const cards = parseCards(result).slice(0, 27); const questions = parseQuestions(result).slice(0, Math.max(1, questionCount)); const cardValidation = validateGeneratedCards(cards); const questionValidation = validateGeneratedQuestions(questions); if (!cardValidation.valid || !questionValidation.valid) return toast.error([...cardValidation.errors, ...questionValidation.errors].join(" ")); if (cardValidation.warnings.length || questionValidation.warnings.length) toast.warning([...cardValidation.warnings, ...questionValidation.warnings].join(" ")); const createdAt = new Date().toISOString(); const set: FlashcardSet = { id: uid(), title: `${title} · Flashcard`, subject, topic, difficulty, createdAt, studyCount: 0, cards }; const quiz: Quiz = { id: uid(), title: `${title} · Đề kiểm tra`, subject, topic, difficulty, durationMinutes: Math.max(1, durationMinutes), createdAt, questions }; onProfile({ ...profile, flashcardSets: [set, ...profile.flashcardSets], quizzes: [quiz, ...profile.quizzes] }, `Đã tạo ${cards.length} Flashcard và đề ${questions.length} câu.`); onView("flashcards"); return; } if (tab === "cards") { const cards = parseCards(result).slice(0, 27); const validation = validateGeneratedCards(cards); if (!validation.valid) return toast.error(validation.errors.join(" ")); if (validation.warnings.length) toast.warning(validation.warnings.join(" ")); const set: FlashcardSet = { id: uid(), title, subject, topic, difficulty, createdAt: new Date().toISOString(), studyCount: 0, cards }; onProfile({ ...profile, flashcardSets: [set, ...profile.flashcardSets] }, `Đã tạo ${cards.length} Flashcard.`); onView("flashcards"); } else { const questions = parseQuestions(result).slice(0, Math.max(1, questionCount)); const validation = validateGeneratedQuestions(questions); if (!validation.valid) return toast.error(validation.errors.join(" ")); if (validation.warnings.length) toast.warning(validation.warnings.join(" ")); const quiz: Quiz = { id: uid(), title, subject, topic, difficulty, durationMinutes: Math.max(1, durationMinutes), createdAt: new Date().toISOString(), questions }; onProfile({ ...profile, quizzes: [quiz, ...profile.quizzes] }, `Đã tạo đề ${questions.length} câu.`); onView("quizzes"); } };
  return <><Heading eyebrow="AI Studio" title="Biến tài liệu thành trải nghiệm học tập" text="Sao chép prompt chuẩn sang AI bên ngoài, sau đó dán kết quả JSON để tạo dữ liệu học cho riêng tài khoản này." /><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><section className="panel p-5"><div className="flex rounded-xl bg-slate-100 p-1 dark:bg-white/5"><button className={cn("tab", tab === "cards" && "selected")} onClick={() => setTab("cards")}>Flashcard</button><button className={cn("tab", tab === "quiz" && "selected")} onClick={() => setTab("quiz")}>Đề kiểm tra</button><button className={cn("tab", tab === "both" && "selected")} onClick={() => setTab("both")}>Cả hai</button></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><Input label="Tên bộ / đề" value={title} set={setTitle} placeholder="Ví dụ: Khí lý tưởng" /><Input label="Môn học" value={subject} set={setSubject} placeholder="Ví dụ: Vật lí 12" /><Input label="Mục đích học" value={purpose} set={setPurpose} placeholder="Ví dụ: ôn thi học kỳ, hiểu bản chất" /><Input label="Chủ đề" value={topic} set={setTopic} placeholder="Ví dụ: Định luật Charles" /><Input label="Lớp học" value={schoolLevel} set={setSchoolLevel} placeholder="Ví dụ: 12" /><label className="block text-sm font-bold">Mức độ<select value={difficulty} onChange={(e) => setDifficulty(e.target.value as typeof difficulty)} className="input"><option>Cơ bản</option><option>Trung bình</option><option>Nâng cao</option></select></label>{tab !== "cards" && <><label className="block text-sm font-bold">Số câu<input type="number" min={1} max={100} value={questionCount} onChange={(e) => setQuestionCount(Number(e.target.value))} className="input" /></label><label className="block text-sm font-bold">Thời gian (phút)<input type="number" min={1} max={180} value={durationMinutes} onChange={(e) => setDurationMinutes(Number(e.target.value))} className="input" /></label></>}</div><label className="mt-4 block text-sm font-bold">Yêu cầu chi tiết<textarea value={requirements} onChange={(e) => setRequirements(e.target.value)} rows={3} className="textarea" placeholder="Ví dụ: ưu tiên khái niệm trọng tâm, có ví dụ thực tế…" /></label><label className="mt-4 block text-sm font-bold">Tài liệu hoặc yêu cầu<textarea value={source} onChange={(e) => setSource(e.target.value)} rows={6} className="textarea" placeholder="Dán tài liệu hoặc yêu cầu học tập. Nội dung này dùng để tạo prompt." /></label><label className="mt-3 block text-sm font-bold">Tải tài liệu TXT, MD hoặc PDF<input type="file" accept=".txt,.md,.pdf,text/plain,text/markdown,application/pdf" className="input mt-1" onChange={async (e) => { const file = e.target.files?.[0]; if (!file) return; setSourceFileName(file.name); const contentType = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf") ? "application/pdf" : file.name.toLowerCase().endsWith(".md") ? "text/markdown" : "text/plain"; setSourceFileContentType(contentType); const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); }); setSourceFileDataUrl(dataUrl); if (file.type === "text/plain" || file.name.endsWith(".md") || file.name.endsWith(".txt")) { const text = await file.text(); setSourceFileContent(text.slice(0, 120000)); setSource(text.slice(0, 120000)); } else { setSourceFileContent(`Tệp PDF đính kèm: ${file.name}. Hãy sử dụng nội dung tệp PDF này làm nguồn chính khi biên soạn.`); } }} /><small className="mt-1 block text-xs text-slate-500">{sourceFileName ? `Đã chọn: ${sourceFileName}` : "TXT/MD được đọc trực tiếp; PDF được giữ làm nguồn tài liệu để gửi cùng yêu cầu."}</small></label>{tab !== "cards" && <div className="mt-4 grid gap-4 sm:grid-cols-3"><Input label="Trắc nghiệm %" value={String(multipleRatio)} set={(value) => setMultipleRatio(Math.min(100, Math.max(0, Number(value) || 0)))} placeholder="60" /><Input label="Đúng/sai %" value={String(booleanRatio)} set={(value) => setBooleanRatio(Math.min(100 - multipleRatio, Math.max(0, Number(value) || 0)))} placeholder="20" /><div className="rounded-xl bg-slate-50 p-3 text-xs font-bold text-slate-500 dark:bg-white/5">Trả lời ngắn<br /><b className="text-lg text-amber-700">{shortRatio}%</b></div><label className="block text-sm font-bold">Số lựa chọn<input type="number" min={2} max={6} value={answerOptionCount} onChange={(e) => setAnswerOptionCount(Math.min(6, Math.max(2, Number(e.target.value) || 2)))} className="input" /></label><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={includeAnswerKey} onChange={(e) => setIncludeAnswerKey(e.target.checked)} />Kèm đáp án mẫu</label></div>}</section><section className="rounded-3xl bg-gradient-to-br from-[#2d211a] via-[#5c4028] to-[#9a6a2f] p-5 text-white"><p className="text-xs font-bold uppercase tracking-widest text-amber-200">Bước 1 · Prompt chuẩn</p><textarea aria-label="Prompt AI có thể chỉnh sửa" value={promptDraft} onChange={(e) => setPromptDraft(e.target.value)} rows={10} className="mt-4 w-full rounded-2xl bg-black/20 p-4 text-sm leading-6 text-amber-50/90 outline-none ring-1 ring-white/10" /><div className="mt-4 grid gap-2 sm:grid-cols-2"><button onClick={() => { setPromptDraft(generatedPrompt); toast.success("Đã tạo lại prompt từ biểu mẫu."); }} className="rounded-xl bg-amber-300 py-3 text-sm font-bold text-slate-950">Tạo lại prompt</button><button onClick={() => navigator.clipboard.writeText(promptDraft || generatedPrompt).then(() => toast.success("Đã sao chép prompt."))} className="rounded-xl bg-amber-200 py-3 text-sm font-bold text-slate-950">Sao chép prompt</button><button disabled={generateFromDocument.isPending} onClick={generate} className="rounded-xl bg-amber-300 py-3 text-sm font-bold text-slate-950">{generateFromDocument.isPending ? "Đang tạo…" : "Tạo từ tài liệu"}</button></div></section></div><section className="panel mt-5 p-5"><p className="text-xs font-bold uppercase tracking-widest text-slate-400">Bước 3 · Nhập kết quả AI</p><textarea value={result} onChange={(e) => setResult(e.target.value)} rows={9} className="textarea mt-3 font-mono text-xs" placeholder={tab === "cards" ? '[{"front":"Câu hỏi","back":"Đáp án"}]' : '{"questions":[{"type":"multiple","prompt":"...","options":["A","B"],"answer":"A"}]}' } /><button onClick={create} className="primary-button mt-4"><Sparkles className="h-4 w-4" />Tạo {tab === "cards" ? "Flashcard" : tab === "quiz" ? "đề kiểm tra" : "cả hai"}</button><span className="ml-3 text-xs text-slate-500">{tab === "cards" ? "Tối đa 27 thẻ mỗi lượt; không giới hạn số bộ." : tab === "quiz" ? "Hỗ trợ trắc nghiệm, đúng/sai và trả lời ngắn." : "Tạo đồng thời tối đa 27 Flashcard và một đề kiểm tra."}</span></section></>;
}
function Input({ label, value, set, placeholder }: { label: string; value: string; set: (x: string) => void; placeholder: string }) { return <label className="block text-sm font-bold">{label}<input value={value} onChange={(e) => set(e.target.value)} placeholder={placeholder} className="input" /></label>; }
function Cards({ profile, config, onProfile }: { profile: ProfileState; config: AppConfig; onProfile: (p: ProfileState, m?: string) => void }) { const [id, setId] = useState(profile.flashcardSets[0]?.id); const [index, setIndex] = useState(0); const [flipped, setFlipped] = useState(false); const [studyMode, setStudyMode] = useState<"flip" | "choice" | "write" | "rapid">("flip"); const [writeAnswer, setWriteAnswer] = useState(""); const [sessionStats, setSessionStats] = useState({ total: 0, known: 0, learning: 0, xp: 0 }); const [showReport, setShowReport] = useState(false); const [rapidSeconds, setRapidSeconds] = useState(0); const [rapidExpired, setRapidExpired] = useState(false); const rapidLimitSeconds = 60; useEffect(() => { if (studyMode !== "rapid") { setRapidSeconds(0); setRapidExpired(false); return; } const started = Date.now(); const timer = window.setInterval(() => { const elapsed = Math.floor((Date.now() - started) / 1000); setRapidSeconds(elapsed); if (elapsed >= rapidLimitSeconds) { setRapidExpired(true); window.clearInterval(timer); } }, 1000); return () => window.clearInterval(timer); }, [studyMode]); const [setQuery, setSetQuery] = useState(""); const [setDifficulty, setSetDifficulty] = useState("all"); const [setDateFilter, setSetDateFilter] = useState("all"); const filteredSets = profile.flashcardSets.filter((x) => { const matchesText = !setQuery || `${x.title} ${x.subject} ${x.topic}`.toLowerCase().includes(setQuery.toLowerCase()); const matchesDifficulty = setDifficulty === "all" || x.difficulty === setDifficulty; const createdAt = new Date(x.createdAt).getTime(); const cutoff = Date.now() - (setDateFilter === "7d" ? 7 : 30) * 86400000; const matchesDate = setDateFilter === "all" || (Number.isFinite(createdAt) && createdAt >= cutoff); return matchesText && matchesDifficulty && matchesDate; }); const set = profile.flashcardSets.find((x) => x.id === id) ?? filteredSets[0] ?? profile.flashcardSets[0]; if (!set) return <><Heading eyebrow="Flashcard" title="Không gian ghi nhớ chủ động" text="Tạo bộ học đầu tiên trong AI Studio, sau đó quay lại đây để lật thẻ và theo dõi tiến độ." /><Empty icon={BookOpen} title="Chưa có bộ Flashcard" text="AI Studio sẽ chuyển dữ liệu JSON thành bộ học cho tài khoản này." /></>; const card = set.cards[index] ?? set.cards[0]; const known = set.cards.filter((x) => x.status === "known").length; const mark = (status: "known" | "learning") => { setSessionStats((previous) => ({ total: previous.total + 1, known: previous.known + (status === "known" ? 1 : 0), learning: previous.learning + (status === "learning" ? 1 : 0), xp: previous.xp + (status === "known" ? 8 : 2) })); const sets = profile.flashcardSets.map((s) => s.id === set.id ? { ...s, studyCount: s.studyCount + 1, cards: s.cards.map((c, i) => i === index ? { ...c, status } : c) } : s); const occurredAt = new Date().toISOString(); const xpEarned = status === "known" ? 8 : 2; const reward = applyStudyActivityRewards({ ...profile, flashcardSets: sets }, { id: `flashcard-${set.id}-${card.id}-${occurredAt.slice(0, 10)}`, occurredAt, kind: "flashcard", quantity: 1, durationSeconds: 0, xpEarned }, config); onProfile(reward.profile, status === "known" ? `+${xpEarned} XP · Đã ghi nhận thẻ nhớ${reward.newlyUnlocked.length ? ` · Mở khóa ${reward.newlyUnlocked.length} thành tích` : ""}.` : "Đã đánh dấu cần ôn lại."); }; const normalizeAnswer = (value: string) => value.trim().replace(/\s+/g, " ").toLocaleLowerCase("vi"); const answerChoice = (choice: string) => { setFlipped(true); mark(normalizeAnswer(choice) === normalizeAnswer(card.back) ? "known" : "learning"); }; const answerWrite = () => { if (!writeAnswer.trim()) return; setFlipped(true); mark(normalizeAnswer(writeAnswer) === normalizeAnswer(card.back) ? "known" : "learning"); setWriteAnswer(""); }; const restartSession = () => { setSessionStats({ total: 0, known: 0, learning: 0, xp: 0 }); setShowReport(false); setIndex(0); setFlipped(false); setWriteAnswer(""); setRapidSeconds(0); setRapidExpired(false); }; const renameSet = () => { const title = window.prompt("Tên mới cho bộ Flashcard", set.title)?.trim(); if (!title) return; onProfile({ ...profile, flashcardSets: profile.flashcardSets.map((item) => item.id === set.id ? { ...item, title } : item) }, "Đã đổi tên bộ Flashcard."); }; const copySet = () => { const clone = { ...set, id: uid(), title: `${set.title} · Bản sao`, createdAt: new Date().toISOString(), studyCount: 0, cards: set.cards.map((card) => ({ ...card, id: uid(), status: "new" as const })) }; onProfile({ ...profile, flashcardSets: [clone, ...profile.flashcardSets] }, "Đã sao chép bộ Flashcard."); setId(clone.id); setIndex(0); }; const deleteSet = () => { if (!window.confirm(`Xóa bộ “${set.title}”?`)) return; const remaining = profile.flashcardSets.filter((item) => item.id !== set.id); onProfile({ ...profile, flashcardSets: remaining }, "Đã xóa bộ Flashcard."); setId(remaining[0]?.id); setIndex(0); }; const createQuizFromSet = () => { const quiz = createQuizFromFlashcardSet(set); onProfile({ ...profile, quizzes: [quiz, ...profile.quizzes] }, `Đã tạo đề ôn tập ${quiz.questions.length} câu từ bộ Flashcard.`); };
  return <><Heading eyebrow="Flashcard" title="Học bằng cách chủ động nhớ lại" text="Lật thẻ để kiểm tra trí nhớ, sau đó đánh dấu đã nhớ hoặc cần ôn lại." /><div className="grid gap-5 xl:grid-cols-[280px_1fr]"><aside className="panel p-4"><b className="font-display text-lg">Bộ của bạn</b><input aria-label="Tìm bộ Flashcard" value={setQuery} onChange={(e) => setSetQuery(e.target.value)} placeholder="Tìm theo tên, môn, chủ đề" className="input mt-3" /><select aria-label="Lọc độ khó Flashcard" value={setDifficulty} onChange={(e) => setSetDifficulty(e.target.value)} className="input mt-2"><option value="all">Mọi độ khó</option><option>Cơ bản</option><option>Trung bình</option><option>Nâng cao</option></select><select aria-label="Lọc ngày Flashcard" value={setDateFilter} onChange={(e) => setSetDateFilter(e.target.value)} className="input mt-2"><option value="all">Mọi ngày</option><option value="7d">7 ngày gần đây</option><option value="30d">30 ngày gần đây</option></select><div className="mt-4 space-y-2">{filteredSets.map((x) => <button key={x.id} onClick={() => { setId(x.id); setIndex(0); setFlipped(false); }} className={cn("w-full rounded-xl p-3 text-left", x.id === set.id ? "bg-amber-50 text-amber-900 dark:bg-amber-400/10 dark:text-amber-100" : "hover:bg-slate-50 dark:hover:bg-white/5")}><b className="block truncate text-sm">{x.title}</b><small className="text-xs text-slate-500">{x.cards.length} thẻ · {x.subject}</small></button>)}</div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4"><button aria-label="Đổi tên bộ Flashcard" onClick={renameSet} className="secondary-button px-2 text-xs">Đổi tên</button><button aria-label="Sao chép bộ Flashcard" onClick={copySet} className="secondary-button px-2 text-xs">Sao chép</button><button aria-label="Xóa bộ Flashcard" onClick={deleteSet} className="secondary-button px-2 text-xs text-rose-700">Xóa</button><button aria-label="Tạo đề từ bộ Flashcard" onClick={createQuizFromSet} className="secondary-button px-2 text-xs">Tạo đề</button></div></aside><section><div className="panel p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-2" role="tablist" aria-label="Chế độ học Flashcard"><button aria-selected={studyMode === "flip"} onClick={() => setStudyMode("flip")} className={cn("secondary-button px-3 text-xs", studyMode === "flip" && "bg-amber-100 text-amber-900")}>Lật thẻ</button><button aria-selected={studyMode === "choice"} onClick={() => setStudyMode("choice")} className={cn("secondary-button px-3 text-xs", studyMode === "choice" && "bg-amber-100 text-amber-900")}>Trắc nghiệm</button><button aria-selected={studyMode === "write"} onClick={() => setStudyMode("write")} className={cn("secondary-button px-3 text-xs", studyMode === "write" && "bg-amber-100 text-amber-900")}>Tự viết</button><button aria-selected={studyMode === "rapid"} onClick={() => setStudyMode("rapid")} className={cn("secondary-button px-3 text-xs", studyMode === "rapid" && "bg-amber-100 text-amber-900")}>Tốc độ</button></div><div className="flex justify-between gap-4"><span><p className="text-xs font-bold uppercase tracking-widest text-amber-700">{set.subject}</p><h2 className="mt-1 font-display text-2xl font-bold">{set.title}</h2></span><b className="text-sm">{index + 1}/{set.cards.length}</b></div></div><Progress value={known / set.cards.length * 100} className="mt-4" /></div>{studyMode === "choice" && <div className="mt-4 grid gap-2 sm:grid-cols-2"><p className="sm:col-span-2 text-sm font-bold text-amber-800">Chọn đáp án đúng:</p>{Array.from(new Set([card.back, ...set.cards.filter((item) => item.id !== card.id).map((item) => item.back)])).slice(0, 4).map((choice) => <button key={choice} onClick={() => answerChoice(choice)} className="secondary-button text-left">{choice}</button>)}</div>}{studyMode === "rapid" && <div className="mt-4 flex items-center justify-between rounded-xl bg-amber-50 px-4 py-3 text-sm font-bold text-amber-900 dark:bg-amber-400/10 dark:text-amber-100"><span>Phiên tốc độ · {rapidSeconds}/{rapidLimitSeconds}s</span><span>{rapidExpired ? "Đã hết giờ" : `Đã chấm ${sessionStats.total} thẻ`}</span></div>}{studyMode === "write" && <div className="mt-4 flex gap-2"><input aria-label="Câu trả lời tự viết" value={writeAnswer} onChange={(e) => setWriteAnswer(e.target.value)} placeholder="Nhập đáp án trước khi kiểm tra" className="input" /><button onClick={answerWrite} className="secondary-button">Kiểm tra</button></div>}<button onClick={() => setFlipped(!flipped)} className="mt-5 min-h-[340px] w-full rounded-[2rem] bg-gradient-to-br from-[#4b2e1f] via-[#805b32] to-[#b67b2d] p-8 text-left text-white shadow-xl shadow-amber-500/20"><p className="text-xs font-bold uppercase tracking-widest text-amber-200">{flipped ? "Đáp án" : "Câu hỏi"}</p><p className="mt-14 font-display text-3xl font-bold leading-relaxed">{flipped ? card.back : card.front}</p><p className="mt-12 text-sm text-amber-100">Nhấn vào thẻ để lật.</p></button><div className="mt-5 flex flex-wrap justify-center gap-2"><button onClick={() => { setIndex((index - 1 + set.cards.length) % set.cards.length); setFlipped(false); }} className="icon-button"><ChevronLeft className="h-5 w-5" /></button><button disabled={rapidExpired} onClick={() => mark("learning")} className="secondary-button text-rose-600 disabled:opacity-50">Cần ôn lại</button><button onClick={() => setFlipped(!flipped)} className="secondary-button">Lật thẻ</button><button disabled={rapidExpired} onClick={() => mark("known")} className="rounded-xl bg-emerald-500 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">Đã nhớ</button><button onClick={() => { setIndex((index + 1) % set.cards.length); setFlipped(false); }} className="icon-button"><ChevronRight className="h-5 w-5" /></button><button onClick={() => setShowReport(true)} className="secondary-button">{rapidExpired ? "Xem kết quả tốc độ" : "Báo cáo phiên"}</button></div>{showReport && <div role="status" aria-live="polite" className="session-complete mt-4 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950 dark:border-amber-400/20 dark:bg-amber-400/10 dark:text-amber-100"><b className="font-display text-lg">Báo cáo phiên học</b><p className="mt-2">Đã chấm {sessionStats.total} thẻ · Đúng/đã nhớ {sessionStats.known} · Cần ôn lại {sessionStats.learning} · +{sessionStats.xp} XP.</p><p className="mt-1 text-xs opacity-80">Phần thưởng mảnh ghép và thành tích được cập nhật theo profile sau mỗi lần chấm.</p><button onClick={restartSession} className="secondary-button mt-3">Học lại phiên</button></div>}</section></div></>;
}
function normalizeQuizAnswer(value: string) { return value.normalize("NFKC").trim().replace(/[.,!?;:()[\]{}"'“”‘’]/g, "").replace(/\s+/g, " ").toLocaleLowerCase("vi"); }
function quizAnswerMatches(question: QuizQuestion, given: string) { const actual = normalizeQuizAnswer(given); const expected = normalizeQuizAnswer(question.answer); if (!actual || !expected) return false; if (actual === expected) return true; const actualNumbers = actual.match(/\d+/g); const expectedNumbers = expected.match(/\d+/g); if (actualNumbers?.length && expectedNumbers?.length && actualNumbers.join(" ") === expectedNumbers.join(" ")) return true; return !question.options?.length && actual.length >= 2 && (expected.endsWith(actual) || actual.endsWith(expected)); }
function Quizzes({ profile, config, onProfile }: { profile: ProfileState; config: AppConfig; onProfile: (p: ProfileState, m?: string) => void }) { const [active, setActive] = useState<Quiz | null>(null); const [answers, setAnswers] = useState<Record<string, string>>({}); const [index, setIndex] = useState(0); const [result, setResult] = useState<number | null>(null); if (!profile.quizzes.length && !active) return <><Heading eyebrow="Đề kiểm tra" title="Tự đánh giá sau mỗi chặng học" text="Tạo đề từ AI Studio. Kết quả và XP được giữ riêng cho tài khoản hiện tại." /><Empty icon={CircleHelp} title="Chưa có đề kiểm tra" text="Dùng AI Studio để tạo đề trắc nghiệm, đúng/sai hoặc trả lời ngắn." /></>; if (!active) return <><Heading eyebrow="Đề kiểm tra" title="Chọn một đề để bắt đầu" text="Mỗi lần hoàn thành đề sẽ được tính XP và cập nhật thống kê học tập." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{profile.quizzes.map((q) => <button key={q.id} onClick={() => { setActive(q); setAnswers({}); setIndex(0); setResult(null); }} className="panel p-5 text-left transition hover:-translate-y-1 hover:border-amber-200"><CircleHelp className="h-6 w-6 text-amber-700" /><p className="mt-5 text-xs font-bold uppercase tracking-widest text-amber-700">{q.subject} · {q.difficulty}</p><h2 className="mt-2 font-display text-xl font-bold">{q.title}</h2><p className="mt-5 text-xs text-slate-500">{q.questions.length} câu · {q.durationMinutes} phút</p></button>)}</div></>; const question = active.questions[index]; const finish = () => { const correct = active.questions.filter((q) => quizAnswerMatches(q, answers[q.id] ?? "")).length; setResult(correct); const xp = 20 + correct * 8; const next = { ...profile, xp: profile.xp + xp, attempts: [{ id: uid(), quizId: active.id, completedAt: new Date().toISOString(), correct, total: active.questions.length, accuracy: Math.round(correct / active.questions.length * 100), durationSeconds: 0 }, ...profile.attempts] }; next.level = levelForXp(next.xp); onProfile(next, `Đã nộp bài · +${xp} XP.`); };
  if (result !== null) return <><Heading eyebrow="Kết quả học tập" title={`${Math.round(result / active.questions.length * 100)}% chính xác`} text={`Bạn trả lời đúng ${result}/${active.questions.length} câu. Xem lại đáp án để củng cố kiến thức.`} action={<button onClick={() => setActive(null)} className="secondary-button">Danh sách đề</button>} /><div className="space-y-3">{active.questions.map((q, i) => <div key={q.id} className={cn("panel p-4", quizAnswerMatches(q, answers[q.id] ?? "") ? "border-emerald-200" : "border-rose-200")}><b>{i + 1}. {q.prompt}</b><p className="mt-2 text-sm text-slate-500">Đáp án: <b>{q.answer}</b>{q.explanation ? ` · ${q.explanation}` : ""}</p></div>)}</div></>; return <><Heading eyebrow={`${active.subject} · ${active.difficulty}`} title={active.title} text={`${active.questions.length} câu hỏi · ${active.durationMinutes} phút`} action={<button onClick={() => setActive(null)} className="secondary-button">Danh sách đề</button>} /><div className="grid gap-5 xl:grid-cols-[1fr_250px]"><section className="panel p-6"><div className="flex justify-between"><span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-800">Câu {index + 1}/{active.questions.length}</span><span className="flex items-center gap-2 font-mono font-bold"><Clock3 className="h-4 w-4 text-rose-500" />20:00</span></div><h2 className="mt-10 font-display text-2xl font-bold leading-relaxed">{question.prompt}</h2><Answer question={question} value={answers[question.id] ?? ""} set={(value) => setAnswers((previous) => ({ ...previous, [question.id]: value }))} /><div className="mt-8 flex justify-between"><button onClick={() => setIndex(Math.max(0, index - 1))} className="secondary-button"><ChevronLeft className="h-4 w-4" />Trước</button>{index === active.questions.length - 1 ? <button onClick={finish} className="primary-button">Nộp bài</button> : <button onClick={() => setIndex(index + 1)} className="primary-button">Tiếp<ChevronRight className="h-4 w-4" /></button>}</div></section><aside className="panel p-4"><p className="text-xs font-bold uppercase tracking-widest text-slate-400">Điều hướng câu hỏi</p><div className="mt-4 grid grid-cols-5 gap-2">{active.questions.map((q, i) => <button key={q.id} onClick={() => setIndex(i)} className={cn("grid h-9 place-items-center rounded-lg text-sm font-bold", i === index ? "bg-amber-600 text-white" : answers[q.id] ? "bg-amber-50 text-amber-800" : "bg-slate-100 text-slate-500 dark:bg-white/5")}>{i + 1}</button>)}</div><button className="mt-5 inline-flex items-center gap-2 text-xs font-bold text-amber-600"><Flag className="h-4 w-4" />Đánh dấu câu</button></aside></div></>;
}
function Answer({ question, value, set }: { question: QuizQuestion; value: string; set: (x: string) => void }) { if (question.type === "short") return <textarea value={value} onChange={(e) => set(e.target.value)} rows={4} className="textarea" placeholder="Nhập câu trả lời…" />; const options = question.type === "boolean" ? ["Đúng", "Sai"] : question.options ?? []; return <div className="mt-6 grid gap-3">{options.map((x) => <button key={x} onClick={() => set(x)} className={cn("rounded-xl border p-4 text-left text-sm font-bold", value === x ? "border-amber-400 bg-amber-50 text-amber-900 dark:bg-amber-400/10 dark:text-amber-100" : "border-slate-200 dark:border-white/10")}>{x}</button>)}</div>; }
function Achievements({ profile, config }: { profile: ProfileState; config: AppConfig }) { const all = useMemo(() => generateAchievements(), []); const earned = computedAchievements(profile, config); const unlocked = new Set(earned.map((x) => x.id)); const [status, setStatus] = useState<"all" | "open" | "locked">("all"); const [difficulty, setDifficulty] = useState("all"); const [onlyTitles, setOnlyTitles] = useState(false); const [onlyFragments, setOnlyFragments] = useState(false); const [query, setQuery] = useState(""); const visible = all.filter((a) => (status === "all" || (status === "open" ? unlocked.has(a.id) : !unlocked.has(a.id))) && (difficulty === "all" || a.difficulty === difficulty) && (!onlyTitles || Boolean(a.title)) && (!onlyFragments || a.rewardFragments > 0) && (!query || `${a.name} ${a.title ?? ""} ${a.description}`.toLowerCase().includes(query.toLowerCase()))); const completion = all.length ? earned.length / all.length * 100 : 0; return <><Heading eyebrow="900 thành tích · 9 bậc" title="Bộ sưu tập tiến bộ và danh hiệu" text="500 mốc đầu trao huy hiệu, XP và mảnh ghép; 400 mốc cuối trao 400 danh hiệu riêng biệt, mỗi danh hiệu có câu chuyện và điều kiện riêng." action={<span className="rounded-xl bg-amber-50 px-4 py-2 text-sm font-bold text-amber-700">{earned.length}/900 đã mở · {all.filter((a) => a.title).length} danh hiệu</span>} /><section className="panel mb-5 p-5" aria-label="Tiến trình mở khóa thành tích"><div className="flex items-center justify-between gap-3 text-sm"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Tiến trình mở khóa</p><p className="mt-1 font-bold">{earned.length}/900 thành tích · {all.filter((a) => a.title).length}/400 danh hiệu có sẵn</p></div><strong className="text-amber-700">{Math.round(completion)}%</strong></div><div className="mt-3 h-3 overflow-hidden rounded-full bg-slate-100 dark:bg-white/10" role="progressbar" aria-label="Tiến trình mở khóa thành tích" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(completion)}><div className="h-full rounded-full bg-gradient-to-r from-[#c62828] via-[#f4b942] to-[#2e7d32] transition-[width]" style={{ width: `${completion}%` }} /></div></section><div className="panel mb-5 grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-5"><input value={query} onChange={(e) => setQuery(e.target.value)} className="input mt-0 lg:col-span-2" placeholder="Tìm thành tích hoặc danh hiệu…" aria-label="Tìm thành tích hoặc danh hiệu" /><select value={status} onChange={(e) => setStatus(e.target.value as typeof status)} className="input mt-0" aria-label="Lọc trạng thái"><option value="all">Tất cả</option><option value="open">Đã mở khóa</option><option value="locked">Chưa mở khóa</option></select><select value={difficulty} onChange={(e) => setDifficulty(e.target.value)} className="input mt-0" aria-label="Lọc độ khó"><option value="all">Mọi độ khó</option>{["Dễ", "Bình thường", "Khó", "Rất khó", "Cực khó", "Huyền thoại"].map((x) => <option key={x}>{x}</option>)}</select><div className="flex flex-wrap items-center gap-3 text-xs font-bold"><label className="flex items-center gap-2"><input type="checkbox" checked={onlyTitles} onChange={(e) => setOnlyTitles(e.target.checked)} />Có danh hiệu</label><label className="flex items-center gap-2"><input type="checkbox" checked={onlyFragments} onChange={(e) => setOnlyFragments(e.target.checked)} />Có mảnh ghép</label></div></div><p className="mb-3 text-sm font-bold text-slate-500">Đang hiển thị {visible.length}/900 mục · {visible.filter((a) => a.title).length} danh hiệu trong bộ lọc</p><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{visible.map((a) => { const isOpen = unlocked.has(a.id); return <article key={a.id} className={cn("achievement-card--unlocked rounded-2xl border p-4", isOpen ? "border-amber-200 bg-amber-50/50 dark:bg-amber-400/10" : "border-slate-200 bg-white/60 dark:border-white/10 dark:bg-white/[.025]")}><div className="flex gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-white text-lg shadow-sm dark:bg-slate-800">{isOpen ? a.icon : "🔒"}</span><span className="min-w-0"><p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">#{all.indexOf(a) + 1} · Bậc {a.rank} · {a.rankName}</p><b className="block text-sm">{isOpen ? a.name : "Một cột mốc đang chờ Ong"}</b><p className="mt-1 text-xs text-slate-500">{isOpen ? a.description : "Mở khóa để khám phá điều kiện và phần thưởng."}</p></span></div><div className="mt-3 flex flex-wrap gap-2 text-[11px] font-bold"><span className="rounded-full bg-slate-100 px-2 py-1 text-slate-600 dark:bg-white/10 dark:text-amber-50/80">{a.difficulty}</span><span className="rounded-full bg-amber-100 px-2 py-1 text-amber-700">{isOpen ? "Đã mở khóa" : "Đang khóa"}</span><span className="rounded-full bg-amber-100 px-2 py-1 text-amber-800">+{a.rewardXp} XP</span></div>{isOpen && a.title && <div className="mt-3 rounded-xl border border-amber-200 bg-gradient-to-r from-amber-100 to-yellow-50 p-3 dark:border-amber-400/30 dark:from-amber-400/15 dark:to-white/5"><p className="text-[10px] font-bold uppercase tracking-widest text-amber-700">Danh hiệu riêng</p><b className="mt-1 block text-sm text-amber-900 dark:text-amber-100">{a.title}</b><p className="mt-1 text-xs leading-5 text-amber-800/80 dark:text-amber-100/70">{a.titleMeaning}</p></div>}<p className="mt-3 text-xs text-slate-500">{isOpen ? a.encouragement : `Phần thưởng: ${a.rewardXp} XP${a.rewardFragments ? ` · ${a.rewardFragments} mảnh ghép` : ""}.`}</p></article>; })}</div></>; }
function Museum({ account, profile, config }: { account: StudyAccount; profile: ProfileState; config: AppConfig }) { if (!config.characters.length) return <><Heading eyebrow="Bảo tàng hành trình" title="Học để mở khóa những câu chuyện" text="Bảo tàng không có dữ liệu mặc định. Mọi nhân vật, nguồn và ảnh đều do Admin/Founder nhập vào." /><Empty icon={History} title="Chưa có dữ liệu nhân vật" text={isAdmin(account) ? "Mở Admin Panel để thêm nhân vật, tiểu sử, mốc lịch sử và nguồn tham khảo." : "Admin/Founder sẽ công bố dữ liệu lịch sử đã được xác minh khi sẵn sàng."} /></>; return <><Heading eyebrow="Bảo tàng hành trình" title="Học để mở khóa những câu chuyện" text="Thu thập mảnh ghép để khám phá các nhân vật lịch sử." /><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{config.characters.map((c) => { const owned = profile.fragments[c.id] ?? 0; const unlocked = owned >= c.fragmentTotal; return <article key={c.id} className="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm dark:border-white/10 dark:bg-slate-900"><div className="relative grid h-48 place-items-center bg-gradient-to-br from-[#8d5d15] to-amber-500">{c.imageUrl ? <img src={c.imageUrl} alt={unlocked ? c.name : "Nhân vật đang khóa"} className={cn("h-full w-full object-cover", !unlocked && "blur-md brightness-50")} /> : <History className="h-12 w-12 text-white/30" />}{!unlocked && <LockKeyhole className="absolute h-7 w-7 text-white" />}</div><div className="p-5"><p className="text-xs font-bold uppercase tracking-widest text-amber-700">{c.role || "Nhân vật lịch sử"}</p><h2 className="mt-1 font-display text-xl font-bold">{unlocked ? c.name : "Nhân vật chưa mở khóa"}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{unlocked ? c.summary || "Chưa có mô tả." : "Thu thập mảnh ghép để khám phá câu chuyện."}</p><Progress value={owned / c.fragmentTotal * 100} className="mt-4" /><p className="mt-2 text-xs font-bold text-slate-500">{owned}/{c.fragmentTotal} mảnh ghép</p></div></article>; })}</div></>; }
function Wheel({ profile, config, onProfile }: { profile: ProfileState; config: AppConfig; onProfile: (p: ProfileState, m?: string) => void }) { const [spinning, setSpinning] = useState(false); const [result, setResult] = useState(""); const spin = () => { if (!profile.wheelTickets) return toast.error("Bạn chưa có vé quay."); if (!config.wheelRewards.length) return toast.error("Vòng quay chưa được cấu hình."); setSpinning(true); const reward = config.wheelRewards[Math.floor(Math.random() * config.wheelRewards.length)]; setTimeout(() => { const next = { ...profile, wheelTickets: profile.wheelTickets - 1, xp: profile.xp + (reward.kind === "xp" ? reward.value : 0) }; next.level = levelForXp(next.xp); onProfile(next, `Nhận được ${reward.label}.`); setResult(reward.label); setSpinning(false); }, 1000); }; return <><Heading eyebrow="Vòng quay tri thức" title="Một phần thưởng cho nỗ lực học tập" text="Admin/Founder cấu hình phần thưởng, màu sắc và tỷ lệ quay." action={<span className="rounded-xl bg-amber-50 px-4 py-2 text-sm font-bold text-amber-800">{profile.wheelTickets} vé</span>} /><div className="grid gap-5 lg:grid-cols-2"><section className="grid min-h-96 place-items-center rounded-[2rem] bg-gradient-to-br from-[#4b2e1f] via-[#805b32] to-[#b67b2d] p-8 text-center text-white"><div className={cn("grid h-64 w-64 place-items-center rounded-full border-[14px] border-white/80 bg-[conic-gradient(#f4c95d_0deg_70deg,#b67b2d_70deg_150deg,#ead7a1_150deg_220deg,#8f6b3d_220deg_300deg,#d8923d_300deg_360deg)]", spinning && "animate-spin")}><span className="grid h-32 w-32 place-items-center rounded-full bg-[#2d211a] font-display font-bold">TRI THỨC</span></div><button onClick={spin} disabled={spinning} className="mt-8 rounded-xl bg-amber-300 px-6 py-3 text-sm font-bold text-[#2d211a] disabled:opacity-50">{spinning ? "Đang quay…" : "Quay ngay"}</button>{result && <p className="mt-4 text-sm font-bold text-amber-200">Phần thưởng: {result}</p>}</section><section className="panel p-6"><p className="text-xs font-bold uppercase tracking-widest text-slate-400">Bảng phần thưởng</p>{config.wheelRewards.length ? <div className="mt-4 grid gap-3 sm:grid-cols-2">{config.wheelRewards.map((r) => <div className="rounded-2xl border border-slate-100 p-4 dark:border-white/10" key={r.id}><span className="block h-2 w-10 rounded-full" style={{ background: r.color }} /><b className="mt-3 block text-sm">{r.label}</b><small className="text-slate-500">Tỷ lệ {r.probability}% · Giá trị {r.value}</small></div>)}</div> : <Empty icon={Dices} title="Chưa có phần thưởng" text="Admin/Founder cần cấu hình ít nhất một ô quay." />}</section></div></>; }
function Account({ account, profile, onProfile, onLogout }: { account: StudyAccount; profile: ProfileState; onProfile: (p: ProfileState, m?: string) => void; onLogout: () => void }) { const exportData = () => { const blob = new Blob([JSON.stringify({ profile }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "study-historia-backup.json"; a.click(); URL.revokeObjectURL(url); }; const importData = (e: ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { onProfile(normalizeProfile(JSON.parse(String(reader.result)).profile ?? JSON.parse(String(reader.result))), "Đã nhập dữ liệu cá nhân."); } catch { toast.error("Tệp JSON không hợp lệ."); } }; reader.readAsText(file); }; return <><Heading eyebrow="Tài khoản cá nhân" title="Dữ liệu của bạn, hành trình của bạn" text="Hồ sơ học tập được cô lập theo mã tài khoản, có thể sao lưu và khôi phục bằng JSON." /><div className="grid gap-5 lg:grid-cols-2"><section className="rounded-3xl bg-gradient-to-br from-[#8d5d15] to-amber-500 p-6 text-white"><p className="text-xs font-bold uppercase tracking-widest text-amber-100">Hồ sơ thành viên</p><h2 className="mt-3 font-display text-3xl font-bold">{account.name}</h2><p className="mt-1 text-amber-100">{account.role} · Mã {account.code}</p><p className="mt-8 text-xl font-bold">Cấp {profile.level} · {profile.xp} XP</p></section><section className="panel p-6"><h2 className="font-display text-2xl font-bold">Sao lưu và riêng tư</h2><p className="mt-3 text-sm leading-6 text-slate-500">Bản sao lưu chỉ gồm dữ liệu học tập của tài khoản hiện tại, không chứa mật khẩu hay dữ liệu thành viên khác.</p><div className="mt-6 flex flex-wrap gap-3"><button onClick={exportData} className="primary-button"><Download className="h-4 w-4" />Xuất JSON</button><label className="secondary-button cursor-pointer"><FileUp className="h-4 w-4" />Nhập JSON<input type="file" className="hidden" accept="application/json" onChange={importData} /></label><button onClick={onLogout} className="secondary-button text-rose-600">Đăng xuất</button></div></section></div></>; }
function Admin({ account, config, onConfig }: { account: StudyAccount; config: AppConfig; onConfig: (c: AppConfig, m?: string) => void }) { const [tab, setTab] = useState<"characters" | "wheel">("characters"); const [name, setName] = useState(""); const [reward, setReward] = useState(""); if (!isAdmin(account)) return <Empty icon={ShieldCheck} title="Khu vực giới hạn" text="Chỉ Admin và Founder có quyền truy cập." />; const addCharacter = () => { if (!name.trim()) return toast.error("Nhập tên nhân vật trước khi thêm."); onConfig({ ...config, characters: [{ id: uid(), name, aliases: "", birthYear: "", deathYear: "", hometown: "", role: "", categories: [], summary: "", biography: "", sourceName: "", sourceUrl: "", imageUrl: "", imageSource: "", fragmentTotal: 12, timeline: [], updatedAt: new Date().toISOString() }] }, "Đã thêm khung nhân vật. Hãy bổ sung nguồn và tiểu sử đã kiểm chứng."); setName(""); }; const addReward = () => { if (!reward.trim()) return toast.error("Nhập tên phần thưởng."); onConfig({ ...config, wheelRewards: [...config.wheelRewards, { id: uid(), label: reward, kind: "xp", value: 20, probability: 20, color: "#22d3ee" }] }, "Đã thêm phần thưởng."); setReward(""); }; return <><Heading eyebrow="Khu vực quản trị" title="Cấu hình hệ sinh thái học tập" text="Admin/Founder quản lý nội dung chung; dữ liệu học tập của mỗi thành viên vẫn tách biệt hoàn toàn." /><div className="flex gap-2"><button onClick={() => setTab("characters")} className={cn("filter-pill", tab === "characters" && "active")}>Nhân vật</button><button onClick={() => setTab("wheel")} className={cn("filter-pill", tab === "wheel" && "active")}>Vòng quay</button></div>{tab === "characters" ? <section className="panel mt-5 p-5"><h2 className="font-display text-xl font-bold">Thêm nhân vật lịch sử</h2><p className="mt-2 text-sm text-slate-500">Không có dữ liệu mẫu. Chỉ nhập nội dung đã xác minh, kèm nguồn và ảnh trong quy trình biên tập tiếp theo.</p><div className="mt-5 flex flex-col gap-3 sm:flex-row"><input value={name} onChange={(e) => setName(e.target.value)} className="input mt-0 flex-1" placeholder="Tên nhân vật" /><button onClick={addCharacter} className="primary-button"><Plus className="h-4 w-4" />Thêm khung</button></div><div className="mt-6 space-y-2">{config.characters.length ? config.characters.map((x) => <div key={x.id} className="flex justify-between rounded-xl border border-slate-100 p-3 dark:border-white/10"><b>{x.name}</b><button onClick={() => onConfig({ ...config, characters: config.characters.filter((c) => c.id !== x.id) }, "Đã xóa nhân vật.")} className="text-rose-600"><X className="h-4 w-4" /></button></div>) : <Empty icon={History} title="Danh sách trống" text="Thêm nhân vật khi đã có nội dung và nguồn hợp lệ." />}</div></section> : <section className="panel mt-5 p-5"><h2 className="font-display text-xl font-bold">Cấu hình vòng quay</h2><div className="mt-5 flex gap-3"><input value={reward} onChange={(e) => setReward(e.target.value)} className="input mt-0 flex-1" placeholder="Ví dụ: +20 XP" /><button onClick={addReward} className="primary-button"><Plus className="h-4 w-4" />Thêm</button></div><div className="mt-6 space-y-2">{config.wheelRewards.map((x) => <div key={x.id} className="flex justify-between rounded-xl border border-slate-100 p-3 dark:border-white/10"><span><b>{x.label}</b><small className="ml-2 text-slate-500">{x.probability}%</small></span><button onClick={() => onConfig({ ...config, wheelRewards: config.wheelRewards.filter((r) => r.id !== x.id) }, "Đã xóa phần thưởng.")} className="text-rose-600"><X className="h-4 w-4" /></button></div>)}</div></section>}</>; }
